import { PASSWORD, USERS, expect, expectStatus, test, uniqueName } from "../fixtures";

test.describe("vendor lifecycle: re-uploaded documents", () => {
  test(
    "a re-uploaded w9 is the one that gets reviewed",
    { tag: "@LIF-01" },
    async ({ apiAs, factory }) => {
      // Arrange
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");
      const vendorName = uniqueName("LIF-01 Vendor");

      const vendorRes = await member.post("/api/vendors", {
        data: { name: vendorName, category: "services", contact_email: "ops@lif01.test" },
      });
      const vendor = await expectStatus<{ id: string; status: string }>(vendorRes, 201);
      expect(vendor.status).toBe("draft");

      const insuranceRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: { name: "insurance.pdf", mimeType: "application/pdf", buffer: Buffer.from("insurance") },
        },
      });
      await expectStatus(insuranceRes, 201);

      const contractRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "contract",
          file: { name: "contract.pdf", mimeType: "application/pdf", buffer: Buffer.from("contract") },
        },
      });
      await expectStatus(contractRes, 201);

      const firstW9Res = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "w9",
          file: {
            name: "w9-first.pdf",
            mimeType: "application/pdf",
            buffer: Buffer.from("Legal name: First Name LLC"),
          },
        },
      });
      const firstW9 = await expectStatus<{ id: string }>(firstW9Res, 201);

      const secondW9Res = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "w9",
          file: {
            name: "w9-second.pdf",
            mimeType: "application/pdf",
            buffer: Buffer.from("Legal name: Second Name LLC"),
          },
        },
      });
      const secondW9 = await expectStatus<{ id: string }>(secondW9Res, 201);

      // Act: submit the vendor, then have a reviewer open the queue.
      const submitRes = await member.post(`/api/vendors/${vendor.id}/submit`);
      const submitted = await expectStatus<{ id: string; status: string }>(submitRes, 200);
      expect(submitted.status).toBe("in_review");

      const queueRes = await reviewer.get("/api/review-queue");
      const queue = await expectStatus<
        Array<{
          vendor_id: string;
          extractions: Array<{ document_id: string; kind: string; fields: Record<string, { value: string | null }> }>;
        }>
      >(queueRes, 200);

      // Assert: the queue entry for this vendor shows the second w9's legal name.
      const item = queue.find((q) => q.vendor_id === vendor.id);
      expect(item, "vendor should appear in the review queue").toBeDefined();
      const w9Extraction = item!.extractions.find((e) => e.kind === "w9");
      expect(w9Extraction, "queue should include a w9 extraction").toBeDefined();
      expect(w9Extraction!.document_id).toBe(secondW9.id);
      expect(w9Extraction!.document_id).not.toBe(firstW9.id);
      expect(w9Extraction!.fields.legal_name?.value).toBe("Second Name LLC");

      // Assert: documents list both w9 uploads, oldest first.
      const docsRes = await member.get(`/api/vendors/${vendor.id}/documents`);
      const docs = await expectStatus<Array<{ id: string; kind: string; created_at: string }>>(docsRes, 200);
      const w9Docs = docs.filter((d) => d.kind === "w9");
      expect(w9Docs.map((d) => d.id)).toEqual([firstW9.id, secondW9.id]);
      const times = w9Docs.map((d) => Date.parse(d.created_at));
      expect(times[0]).toBeLessThanOrEqual(times[1]);
    },
  );
});
